// The Form Trigger's uploaded file arrives under a binary key derived from
// the field label (e.g. "Cleaned_CSV"), not a fixed name. Normalize it to
// "data" so "Parse CSV" can reference a predictable binary property.
const items = $input.all();
for (const item of items) {
  const keys = Object.keys(item.binary || {});
  if (keys.length && !item.binary.data) {
    item.binary.data = item.binary[keys[0]];
  }
}
return items;

// Normalize each cleaned-CSV row into the shapes the GHL API calls need.
// Column names below must match the cleaned CSV's headers exactly (case-sensitive).
// Edit the keys inside get('...') if your headers differ.
//
// Workflow-level constants — edit the values below directly.
// Leave a custom field id blank ('') if you don't have that field in GHL yet;
// it's skipped rather than sent as an invalid id. stageColdLeadId blank means
// GHL will drop the new opportunity into the pipeline's default stage instead
// of "Cold Lead" specifically — fill it in once you find it and future rows
// will land in the right stage (already-created ones can be moved manually).
const cfg = {
  locationId: 'ePctRAWdzLzdap3o1H4S',
  pipelineId: 'vFY6pqeYysx9GMHwyr8j',
  stageColdLeadId: '',
  cfContactBusinessUnit: '',
  cfContactReferralSource: '',
  cfContactPhone2: '',
  cfContactPhone3: '',
  cfContactEmail2: '',
  cfOppTierRank: '',
  cfOppCloseScore: '',
  cfOppCurrentManager: '',
  cfOppPitchAngle: '',
  cfOppListingUrl: '',
};
const has = (v) => Boolean(v);
const locationId = cfg.locationId;
const items = $input.all();
const out = [];

for (const item of items) {
  const r = item.json;
  const get = (k) => (r[k] === undefined || r[k] === null) ? '' : String(r[k]).trim();

  const name = get('Owner Name');
  const phone1 = get('Phone 1');
  const phone2 = get('Phone 2');
  const phone3 = get('Phone 3');
  const email1 = get('Email 1');
  const email2 = get('Email 2');
  const city = get('City');
  const state = get('State');
  const referralSource = get('Referral Source');
  const listingTitle = get('Listing Title');
  const listingUrl = get('Listing URL');
  const tierRank = get('Tier Rank');
  const dataQualityFlag = get('Data Quality Flag');
  const closeScore = get('Close Score');
  const currentManager = get('Current Manager');
  const pitchAngle = get('Pitch Angle');

  const dnd = dataQualityFlag.toLowerCase() === 'do not contact';

  // Contact-level duplicate check: match on phone and/or email, whichever exist.
  const searchQuery = { locationId };
  if (email1) searchQuery.email = email1;
  if (phone1) searchQuery.number = phone1;

  // GHL's core Contact object only has ONE native phone + ONE native email.
  // Phone 2/3 and Email 2 go out as Contact custom fields instead.
  const contactCustomFields = [];
  if (has(cfg.cfContactBusinessUnit)) {
    contactCustomFields.push({ id: cfg.cfContactBusinessUnit, fieldValue: 'WavyStay' });
  }
  if (referralSource && has(cfg.cfContactReferralSource)) {
    contactCustomFields.push({ id: cfg.cfContactReferralSource, fieldValue: referralSource });
  }
  if (phone2 && has(cfg.cfContactPhone2)) {
    contactCustomFields.push({ id: cfg.cfContactPhone2, fieldValue: phone2 });
  }
  if (phone3 && has(cfg.cfContactPhone3)) {
    contactCustomFields.push({ id: cfg.cfContactPhone3, fieldValue: phone3 });
  }
  if (email2 && has(cfg.cfContactEmail2)) {
    contactCustomFields.push({ id: cfg.cfContactEmail2, fieldValue: email2 });
  }

  const createContactBody = {
    locationId,
    name: name || undefined,
    phone: phone1 || undefined,
    email: email1 || undefined,
    city: city || undefined,
    state: state || undefined,
    source: 'WavyStay Owner Import',
    tags: ['WS-Lead-Cold', 'WS-Import-CoHost-Priority-Sep2026'],
    customFields: contactCustomFields,
  };

  // Opportunity-level fields — this is the data the native GHL importer can't touch.
  const opportunityCustomFields = [];
  if (has(cfg.cfOppTierRank)) opportunityCustomFields.push({ id: cfg.cfOppTierRank, fieldValue: tierRank });
  if (has(cfg.cfOppCloseScore)) opportunityCustomFields.push({ id: cfg.cfOppCloseScore, fieldValue: closeScore });
  if (has(cfg.cfOppCurrentManager)) opportunityCustomFields.push({ id: cfg.cfOppCurrentManager, fieldValue: currentManager });
  if (has(cfg.cfOppPitchAngle)) opportunityCustomFields.push({ id: cfg.cfOppPitchAngle, fieldValue: pitchAngle });
  if (has(cfg.cfOppListingUrl)) opportunityCustomFields.push({ id: cfg.cfOppListingUrl, fieldValue: listingUrl });

  out.push({
    json: {
      rowName: name || '(unnamed row)',
      phone1, phone2, phone3, email1, email2,
      city, state, referralSource,
      listingTitle, listingUrl, tierRank, dataQualityFlag, closeScore, currentManager, pitchAngle,
      dnd,
      hasIdentifier: Boolean(phone1 || email1),
      locationId,
      pipelineId: cfg.pipelineId,
      stageColdLeadId: cfg.stageColdLeadId,
      searchQuery,
      createContactBody,
      opportunityCustomFields,
    },
  });
}

return out;

// Normalizes the duplicate-search response (or its caught error) into a
// simple tri-state result so the IF nodes downstream don't need to know
// GHL's response/error shape.
const res = $input.item.json;
let matchStatus = 'not_found';
let contactId = null;
let errorDetail = null;

if (res && res.error) {
  const raw = JSON.stringify(res.error);
  const is404 = raw.indexOf('404') !== -1 || String(res.error.httpCode) === '404' || String(res.error.statusCode) === '404';
  if (is404) {
    matchStatus = 'not_found';
  } else {
    matchStatus = 'search_failed';
    errorDetail = raw.slice(0, 500);
  }
} else if (res && res.contact && res.contact.id) {
  matchStatus = 'found';
  contactId = res.contact.id;
}

return { matchStatus, contactId, errorDetail };
